import React, { useEffect, useState, useCallback, useMemo } from 'react';
import './MarketplaceBanner.less';
import { BackgroundSvg } from './MarketplacebannerBackground';
import { BannerIcon } from './BannerIcon';

// Animation timing constants for better maintainability
const ANIMATION_DURATION_MS = 600;
const WORD_CHANGE_INTERVAL_MS = 3000;

/**
 * Props for the MarketplaceBanner component
 */
interface MarketplaceBannerProps {
  /** Background color of the banner */
  backgroundColor?: string;
  /** Text to be highlighted with gradient styling */
  highlightText?: string;
  /** Array of text options to cycle through with animation */
  nonHighlightTextOptions?: string[];
  /** Optional description text displayed below the main title */
  description?: string | JSX.Element;
  /** Optional size of the banner */
  contentSize?: 'small' | 'large';
}

/**
 * State interface for word animation
 */
interface WordAnimationState {
  currentIndex: number;
  nextIndex: number;
  isAnimating: boolean;
}

/**
 * MarketplaceBanner component that displays a banner with animated text cycling
 *
 * Features:
 * - Gradient highlighted text
 * - Animated cycling of non-highlighted text options
 * - Responsive design
 * - Input validation and sanitization
 */
export const MarketplaceBanner: React.FC<MarketplaceBannerProps> = ({
  backgroundColor,
  highlightText,
  nonHighlightTextOptions = [],
  description,
  contentSize,
}) => {
  // Initialize animation state
  const [animationState, setAnimationState] = useState<WordAnimationState>({
    currentIndex: 0,
    nextIndex: 1,
    isAnimating: false,
  });

  /**
   * Validates and sanitizes the non-highlight text options
   * Filters out empty strings and non-string values for security
   */
  const validTextOptions = useMemo(() => {
    return nonHighlightTextOptions.filter(
      (text): text is string => typeof text === 'string' && text.trim().length > 0, // Prevent extremely long strings
    );
  }, [nonHighlightTextOptions]);

  /**
   * Advances to the next word in the cycle
   */
  const advanceToNextWord = useCallback(() => {
    if (validTextOptions.length <= 1) return;

    setAnimationState((prev) => ({
      ...prev,
      isAnimating: true,
      nextIndex: (prev.currentIndex + 1) % validTextOptions.length,
    }));

    // Complete the animation after the transition duration
    setTimeout(() => {
      setAnimationState((prev) => ({
        currentIndex: (prev.currentIndex + 1) % validTextOptions.length,
        nextIndex: (prev.currentIndex + 2) % validTextOptions.length,
        isAnimating: false,
      }));
    }, ANIMATION_DURATION_MS);
  }, [validTextOptions.length]);

  // Set up word cycling animation
  useEffect(() => {
    if (validTextOptions.length <= 1) return;

    const interval = setInterval(advanceToNextWord, WORD_CHANGE_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [validTextOptions.length, advanceToNextWord]);

  // Don't render if no content is provided
  if (!highlightText && validTextOptions.length === 0) {
    return null;
  }

  const currentWord = validTextOptions[animationState.currentIndex] || '';
  const nextWord = validTextOptions[animationState.nextIndex] || '';

  return (
    <div className={`vim-marketplace-banner ${contentSize === 'small' ? 'small-content' : ''}  `}>
      <BackgroundSvg backgroundColor={backgroundColor}>
        <div className="vim-marketplace-banner-content">
          <div className={`banner-content-title ${!description ? 'single-line' : ''} `}>
            {highlightText && <span className="banner-highlight banner-text">{highlightText}</span>}
            <span className="banner-non-highlight-container">
              <span
                key={`current-${currentWord}-${animationState.currentIndex}`}
                className={`banner-non-highlight banner-text current-word ${
                  animationState.isAnimating ? 'slide-out' : ''
                }`}
              >
                {currentWord}
              </span>
              {animationState.isAnimating && (
                <span
                  key={`next-${nextWord}-${animationState.nextIndex}`}
                  className="banner-non-highlight banner-text next-word slide-in"
                >
                  {nextWord}
                </span>
              )}
            </span>
          </div>
          {description && (
            <div className="banner-content-description">
              <span className="banner-text small">{description}</span>
            </div>
          )}
        </div>
        <BannerIcon size={contentSize || 'large'} />
      </BackgroundSvg>
    </div>
  );
};
